//! Small arrays of encoded keys.
//!
//! - Up to 32 keys: a sorting network of exactly that length (pruned Batcher
//!   networks in `networks.rs`, generated by `tools/gen_networks.py`); each
//!   compare-exchange is a `min` / `max` pair, without branch.
//! - Up to 64 keys: blocks of 32 by their network, then one branch-free merge.
//!
//! Both first return sorted input as is and reverse descending input.

use std::convert::TryFrom;

include!("networks.rs");

/// Largest length sorted by a network.
pub(crate) const NETWORK_MAX: usize = 32;
/// From this length the order probe runs before the network (shorter
/// networks cost about as much as the probe).
const PROBE_MIN: usize = 5;

#[inline(always)]
fn cswap<K: Copy + Ord, const N: usize>(a: &mut [K; N], i: usize, j: usize) {
    let (x, y) = (a[i], a[j]);
    a[i] = x.min(y);
    a[j] = x.max(y);
}

/// Sorts at most `NETWORK_MAX` raw keys in place: `encode` maps them to keys
/// whose unsigned order is the wanted order, `decode` maps them back.
#[inline]
pub(crate) fn network_sort<K: Copy + Ord>(keys: &mut [K], encode: impl Fn(K) -> K, decode: impl Fn(K) -> K) {
    let n = keys.len();
    debug_assert!(n <= NETWORK_MAX);
    if n < 2 {
        return;
    }
    keys.iter_mut().for_each(|k| *k = encode(*k));
    let presorted = n >= PROBE_MIN && sort_if_monotone(keys);
    if !presorted {
        network_any(keys);
    }
    keys.iter_mut().for_each(|k| *k = decode(*k));
}

/// Largest length sorted by `block_merge_sort` (stack buffer size); beyond,
/// `sort_unstable` wins (journal §29).
pub(crate) const MERGE_MAX: usize = 64;
/// Block sorted by a network before the merges.
const BLOCK: usize = 32;

/// Merges the sorted runs `src[..mid]` and `src[mid..n]` into `dst[..n]`.
/// The choice of the next key is a select (no data-dependent branch); the
/// loop condition is predictable.
///
/// # Safety
/// `src` and `dst` valid for `n` keys, not overlapping; `mid <= n`.
#[inline(always)]
unsafe fn merge<K: Copy + Ord>(src: *const K, dst: *mut K, mid: usize, n: usize) {
    let (mut i, mut j, mut k) = (0usize, mid, 0usize);
    unsafe {
        while i < mid && j < n {
            let (a, b) = (*src.add(i), *src.add(j));
            let take_right = b < a;
            *dst.add(k) = if take_right { b } else { a };
            i += usize::from(!take_right);
            j += usize::from(take_right);
            k += 1;
        }
        std::ptr::copy_nonoverlapping(src.add(i), dst.add(k), mid - i);
        k += mid - i;
        std::ptr::copy_nonoverlapping(src.add(j), dst.add(k), n - j);
    }
}

/// Sorts at most `MERGE_MAX` encoded keys: blocks of `BLOCK` keys by their
/// network, then bottom-up merges between the keys and a stack buffer.
#[inline(never)]
pub(crate) fn block_merge_sort<K: Copy + Ord>(keys: &mut [K]) {
    let n = keys.len();
    assert!(n <= MERGE_MAX);
    for block in keys.chunks_mut(BLOCK) {
        if block.len() >= 2 {
            network_any(block);
        }
    }
    if n <= BLOCK {
        return;
    }
    let mut buf = [std::mem::MaybeUninit::<K>::uninit(); MERGE_MAX];
    let (a, b) = (keys.as_mut_ptr(), buf.as_mut_ptr() as *mut K);
    let mut in_keys = true;
    let mut width = BLOCK;
    // SAFETY: each round reads the `n` keys of one side (all written: the
    // keys at first, then the previous round's output) and writes all `n`
    // slots of the other; runs are clipped to `n`.
    unsafe {
        while width < n {
            let (src, dst) = if in_keys { (a as *const K, b) } else { (b as *const K, a) };
            let mut start = 0;
            while start < n {
                let mid = (start + width).min(n);
                let end = (start + 2 * width).min(n);
                merge(src.add(start), dst.add(start), mid - start, end - start);
                start = end;
            }
            in_keys = !in_keys;
            width *= 2;
        }
        if !in_keys {
            std::ptr::copy_nonoverlapping(b as *const K, a, n);
        }
    }
}

/// Sorts at most `MERGE_MAX` raw keys in place: encode, order probe,
/// `block_merge_sort`, decode.
#[inline]
pub(crate) fn merge_sort<K: Copy + Ord>(keys: &mut [K], encode: impl Fn(K) -> K, decode: impl Fn(K) -> K) {
    keys.iter_mut().for_each(|k| *k = encode(*k));
    if !sort_if_monotone(keys) {
        block_merge_sort(keys);
    }
    keys.iter_mut().for_each(|k| *k = decode(*k));
}

/// Ascending keys: nothing to do; descending ones: reversed. Returns
/// whether the keys are now sorted. Branch-free scan.
#[inline(always)]
fn sort_if_monotone<K: Copy + Ord>(keys: &mut [K]) -> bool {
    let (mut ascending, mut descending) = (true, true);
    for pair in keys.windows(2) {
        ascending &= pair[0] <= pair[1];
        descending &= pair[0] >= pair[1];
    }
    if descending && !ascending {
        keys.reverse();
    }
    ascending || descending
}
